    /// </summary>
    [pbr::OriginalName("WARM_INTRO_DECISION_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// The target accepted and was joined
    /// </summary>
    [pbr::OriginalName("WARM_INTRO_DECISION_ACCEPTED")] Accepted = 1,
